// Bài 11.1 — let tạo một i MỚI cho mỗi vòng ⇒ mỗi closure giữ i của vòng đó
function makeHandlers(n) {
  const handlers = [];
  for (let i = 0; i < n; i++) {
    handlers.push(() => 'button ' + i);   // bắt giữ i của RIÊNG vòng này
  }
  return handlers;
}

