// Bài 11.1 — once: done và result sống trong closure của MỖI lần gọi once
function once(fn) {
  let done = false;
  let result;
  return (...args) => {
    if (!done) {
      done = true;             // đánh dấu TRƯỚC khi gọi, kể cả fn ném lỗi cũng không chạy lại
      result = fn(...args);
    }
    return result;
  };
}

